W += [
E('fraternity','英 /frəˈtɜːnəti/；美 /frəˈtɜːrnəti/','兄弟情谊；同业群体；大学兄弟会','一群人因为共同身份、兴趣或目标，把彼此看成同一圈子里的伙伴。','经古法语 fraternité 接拉丁 fraternitas 兄弟关系，来自 fraternus 兄弟般的、frater 兄弟。英语既发展团体义，也保留彼此亲近的抽象关系义。',FRATERNITY,'the medical fraternity 是医学界同仁；美国大学的 a fraternity 常是兄弟会社团。liberty, equality and fraternity 中则是博爱或兄弟情谊，不是三个大学社团。','join a fraternity；the legal fraternity；a spirit of fraternity。','fraternity 可以指关系或团体，brotherhood 也可有这两种意思。sorority 通常指大学姐妹会；fraternity 的一般同业用法不必只限男性。',('She is well known within the scientific fraternity.','她在科学界同仁中很有名。'),('He joined a fraternity during his first year at university.','他在大学一年级加入了一个兄弟会。'),sources=['https://www.etymonline.com/word/fraternity','https://www.oxfordlearnersdictionaries.com/definition/english/fraternity']),
E('fraternal','英 /frəˈtɜːnəl/；美 /frəˈtɜːrnəl/','兄弟的；兄弟般的；异卵双胞胎的','一般形容像兄弟一样亲近、互助；在 twins 前面却是一个明确的生物学分类。','经法语 fraternel 或中世纪拉丁 fraternalis，接拉丁 fraternus 兄弟般的。它不是简单从英语 fraternity 砍去末尾再加 -al。',FRATERN+[['中世纪拉丁 fraternalis → 法语 fraternel／英语 fraternal','兄弟般的；后来也用于异卵双胞胎名称']],'fraternal affection 是兄弟般的关爱。fraternal twins 来自同一次妊娠中两枚卵子分别受精，可能同性，也可能异性；不能按 brother 的字面误以为只指男双胞胎。','fraternal affection；a fraternal organisation；fraternal twins。','identical twins 是同卵双胞胎；fraternal twins 是异卵双胞胎。fraternal 兄弟的与 paternal 父亲的不是同一亲属方向。',('The two clubs maintained a spirit of fraternal cooperation.','两个俱乐部保持着兄弟般的合作精神。'),('The two sisters are fraternal twins.','这两姐妹是异卵双胞胎。'),sources=['https://www.etymonline.com/word/fraternal','https://www.oxfordlearnersdictionaries.com/definition/english/fraternal','https://www.genome.gov/genetics-glossary/Fraternal-Twins']),
E('fraternize','英 /ˈfrætənaɪz/；美 /ˈfrætərnaɪz/','友好交往；亲近往来','原本分属两边或应保持距离的人，却像熟人一样聊起来、来往起来。','经法语 fraterniser 接中世纪拉丁 fraternizare，来自 fraternus 兄弟般的。现代可认出 fratern- 与 -ize，但有完整的法语、拉丁借入路线。',FRATERNIZE,'fraternize with colleagues 可以说同事间交往；fraternize with the enemy 常暗示与本不应亲近的一方友好往来。词不必指恋爱或性关系，具体要看情境。','fraternize with colleagues；fraternize with the enemy；refuse to fraternize。','socialize 普遍说社交，fraternize 常带本来有边界却亲近起来的感觉，有时含批评。英式也常写 fraternise。',('The rival teams fraternized after the match.','两支对手球队在比赛后友好地聊了起来。'),('The commander warned the troops not to fraternize with the enemy.','指挥官告诫士兵不要与敌方人员亲近往来。'),sources=['https://www.etymonline.com/word/fraternize','https://www.oxfordlearnersdictionaries.com/definition/english/fraternize']),
E('fraternization','英 /ˌfrætənaɪˈzeɪʃən/；美 /ˌfrætərnəˈzeɪʃən/','亲善交往；不当亲近往来','把 fraternize 的交往当成一种现象或行为来谈，常见于本来有身份或阵营界限的场景。','fraternize 对应的 -ation 行为名词，形成时也以法语 fraternisation 为参照；英式常写 fraternisation。不能从 fraternity 直接翻成兄弟会。',FRATERNIZE+[['英语 fraternize → fraternization，参照法语 fraternisation','像兄弟般交往的行为；后来常用于纪律所限制的亲近关系']],'fraternization between opposing troops 是敌对军队人员间的友好交往。职场政策中也可能出现这个词，但它具体限制哪种关系由政策语境决定，词本身不等于一律禁止交朋友。','fraternization between groups；rules on fraternization；a ban on fraternization。','friendship 指友谊关系，fraternization 特别强调跨过原有界限的来往行为。fraternity 则是情谊或团体名称。',('The diary describes brief moments of fraternization between the soldiers.','日记记录了士兵之间短暂的友好交往。'),('The handbook explains the organisation’s rules on fraternization.','手册解释了该组织对私人亲近往来的规定。'),sources=['https://www.etymonline.com/word/fraternization','https://www.oxfordlearnersdictionaries.com/definition/english/fraternization']),
E('fratricide','/ˈfrætrɪsaɪd/','杀害兄弟姐妹；手足相残；杀害同胞；误杀友军','本应属于自己这一边的人，却成为伤害或杀戮的对象。','人物义接拉丁 fratricida 杀兄弟者；行为义接 fratricidium，经法语等路线进入英语。fratr- 兄弟 + -cide 杀，后者来自 caedere；行为名词不能只画成人物名词加后缀。',FRAT+[['并列拉丁形式 fratricida 杀兄弟者；fratricidium 杀兄弟的行为','后半接 caedere 杀、砍'],['法语／拉丁借入 → 英语 fratricide','早有人物义，行为义后来常用；扩展到同胞相残和误杀友军']],'历史故事里可以是亲兄弟相杀；战争和政治评论中可以泛说同胞相残。军事术语还可指误杀己方人员；这层意思不表示攻击者与死者有血缘关系。','an act of fratricide；a story of fratricide；prevent fratricide。','homicide 泛指杀人；fratricide 强调手足或己方关系。friendly fire 是友军误击，不表示炮火友善。',('The tragedy centres on an act of fratricide within the royal family.','这部悲剧围绕王室内部的一次手足相残展开。'),('The report examined how misidentification had led to fratricide.','报告调查了误认身份如何导致误杀友军。'),sources=['https://www.etymonline.com/word/fratricide','https://www.oxfordlearnersdictionaries.com/definition/english/fratricide']),
E('fratricidal','/ˌfrætrɪˈsaɪdəl/','手足相残的；同室操戈的；自相残杀的','形容本应同属一家或同一阵营的人互相残害，常带强烈的悲剧和批评意味。','fratricide + -al，去掉末尾 e；名词后半接拉丁表示杀的成分。现代形容词的重音移到 -ci- 这一部分。',FRAT+[['拉丁 fratricida／fratricidium → 英语 fratricide','杀害手足或己方成员'],['英语 fratricide + -al → fratricidal','涉及手足或内部成员相残的']],'a fratricidal war 是同胞之间的战争；a fratricidal struggle 在政治文章里也可比喻派系互相攻击，并不一定真的发生杀人。','a fratricidal conflict；fratricidal warfare；a fratricidal struggle。','internal 只说发生在内部；fratricidal 进一步强调本方互害、两败俱伤。fraternal 是兄弟般的友好，两词感情色彩几乎相反。',('The country was divided by a long fratricidal war.','这个国家因漫长的同胞相残战争而分裂。'),('The party exhausted itself in a fratricidal struggle for control.','这个政党在争夺控制权的内斗中耗尽了力量。'),sources=['https://www.etymonline.com/word/fratricidal','https://www.oxfordlearnersdictionaries.com/definition/english/fratricidal']),
E('friar','英 /ˈfraɪə/；美 /ˈfraɪər/','托钵修士；某些天主教修会的男修士','传统上在民众中传教、服务，并依靠施舍生活的某些修会成员。','中古英语从古法语 frere 借入，往前是拉丁 frater 兄弟。修会成员彼此称兄弟，普通亲属称谓于是成为宗教身份名。',FRAT+[['古法语 frere 兄弟、修士 → 中古英语 frere → friar','保留下来的是特定修会成员名称']],'a Franciscan friar 是方济各会修士；故事里的 Friar Tuck 把 friar 当称号。现代 friar 不一定每天外出乞食，这个名称保留的是修会传统。','a Franciscan friar；a Dominican friar；a community of friars。','monk 通常更突出修道院生活，friar 传统上更强调在人群中服务；两者都不能简单等同于 priest 神父，因为是否受圣职是另一件事。',('A friar welcomed the visitors at the church entrance.','一位修士在教堂入口迎接访客。'),('The novel follows a young Franciscan friar on his travels.','小说讲述一位年轻方济各会修士的旅程。'),sources=['https://www.etymonline.com/word/friar','https://www.oxfordlearnersdictionaries.com/definition/english/friar']),
E('frat','/fræt/','大学兄弟会；兄弟会的','在美国校园语境里，fraternity 的简短口语说法，常放在 party、house 前。','英语 fraternity 截短为 frat。它虽恰好像拉丁 fratr- 的开头，历史上却是英语长词缩短，不是直接借拉丁 frat。',FRATERNITY+[['英语 fraternity → 口语截短 frat','大学兄弟会及其相关活动']],'a frat party 是兄弟会举办的派对，a frat house 是兄弟会会所或住处。语气比 fraternity 随意，正式机构名称通常保留长形式。','a frat party；a frat house；join a frat。','frat 主要是校园社团简称，不通常用来代替 medical fraternity 医学界中的 fraternity。frat boy 是相关男生称呼，有时带对某种校园作风的批评。',('The frat organised a fundraiser for the local food bank.','这个兄弟会为当地食物银行组织了筹款活动。'),('They walked past a crowded frat house on the way home.','回家路上，他们经过一栋挤满人的兄弟会会所。'),sources=['https://www.etymonline.com/word/frat','https://www.oxfordlearnersdictionaries.com/definition/english/frat']),
E('veto','英 /ˈviːtəʊ/；美 /ˈviːtoʊ/','否决权；否决；行使否决权','有权说出一个足以让提案停下来的不，而不只是表达自己不喜欢。','直接来自拉丁 veto，我禁止，是 vetare 禁止的第一人称单数现在时。英语先把这个完整说法当名词，后来再形成动词。',[['拉丁 vetare 禁止 → veto 我禁止','原来是带有人称与时态的完整动词形式'],['英语 veto 名词 → veto 动词','否决权或否决行为 → 行使这种权力']],'exercise a veto 是行使否决权，veto a proposal 是否决提案。日常也能夸张地说家人 vetoed my plan；真正制度里否决如何生效、能否被推翻，要看具体规则。','veto a proposal；exercise a veto；veto power。','oppose 是反对，不一定有权阻止；veto 通常强调有决定性的否决权。vet 审查来自 veterinary 的缩短，是另一路线。名词复数 vetoes，过去式 vetoed。',('The president vetoed the bill.','总统否决了这项法案。'),('My family vetoed my plan to paint the kitchen purple.','家人否决了我把厨房刷成紫色的计划。'),sources=['https://www.etymonline.com/word/veto','https://www.oxfordlearnersdictionaries.com/definition/english/veto_1']),
E('affiliation','/əˌfɪliˈeɪʃən/','隶属关系；所属机构；关联；成员身份','说明你属于哪家机构、哪种团体，或与哪一方有正式联系。','经法语 affiliation 接中世纪拉丁 affiliatio，来自 affiliare 收为子。英语名词记录早于动词 affiliate，不能把历史只写成现代动词加 -ion。',AFF+[['中世纪拉丁 affiliatio → 法语 affiliation → 英语 affiliation','收养关系；后来扩大为组织归属与联系']],'论文表格的 affiliation 常填作者所在机构；political affiliation 是政治归属，religious affiliation 是宗教团体归属。它不是私人好友列表，也不必表示一个机构完全拥有另一个。','institutional affiliation；political affiliation；affiliation with a university。','membership 强调成员资格；affiliation 可以是成员身份，也可以是机构之间的正式关联。association 更宽，可能只是联系或联想。',('Please list your name and institutional affiliation.','请列出姓名及所属机构。'),('The centre has no affiliation with any political party.','这个中心与任何政党都没有隶属或关联关系。'),sources=['https://www.etymonline.com/word/affiliation','https://www.oxfordlearnersdictionaries.com/definition/english/affiliation']),
E('affiliate','动词 /əˈfɪlieɪt/；名词 /əˈfɪliət/','使隶属；加入；关联机构；合作成员','像把一个单位接进更大的组织网络；作名词时，就是网络里与主体有联系的那一方。','动词借中世纪拉丁 affiliat-，接 affiliare 收为子：ad- 向着 + filius 儿子。英语名词后来由动词及相关形容词用法形成；不是 fil- 线。',AFFILIATE+[['英语 affiliate 动词 → 相关形容词、名词 affiliate','纳入关系 → 有关联的机构或成员；名词尾音弱化']],'affiliate with a group 是与团体建立联系；a local affiliate 是当地关联机构。affiliate marketing 中的 affiliate 可以是推广合作方，不一定是对方的子公司或雇员。','affiliate with an organisation；a local affiliate；an affiliate of a larger group。','subsidiary 通常强调控制或所有权关系；affiliate 更宽，具体联系要看上下文。动词末尾 /eɪt/，名词 /ət/，重音都在第二音节。',('The small club decided to affiliate with a national association.','这个小俱乐部决定加入一个全国性协会。'),('A local affiliate broadcast the interview that evening.','一家地方加盟台在当晚播出了那场采访。'),sources=['https://www.etymonline.com/word/affiliate','https://www.oxfordlearnersdictionaries.com/definition/english/affiliate_1','https://www.oxfordlearnersdictionaries.com/definition/english/affiliate_2']),
E('affiliated','/əˈfɪlieɪtɪd/','附属的；有关联的；加入某组织的','描述已经与某个组织建立联系的状态，例如与大学合作的医院或协会的成员机构。','affiliate + -ed；来自动词的过去分词，常作形容词。虽然比喻背景是收为子，今天不涉及真实亲子关系。',AFFILIATE+[['英语 affiliate + -ed → affiliated','已加入、已联系在一起的状态']],'be affiliated with 或 be affiliated to 都常见。an affiliated hospital 是关联、附属医院；具体是否归同一主体所有，不能只凭这个词判断。','be affiliated with；be affiliated to；an affiliated institution。','associated 可以是较一般的联系，affiliated 通常更像有组织的正式关系。affiliated 不等于所有员工都受同一个单位直接雇用。',('The research centre is affiliated with a local university.','这家研究中心与当地一所大学有关联。'),('The invitation was sent to all affiliated clubs.','邀请已发给所有成员俱乐部。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/affiliated','https://www.etymonline.com/word/affiliate']),
E('filial','/ˈfɪliəl/','子女的；子女对父母的；孝顺的','站在子女这一边，谈他们对父母的感情、责任或行为。','借晚期拉丁 filialis 子女的，来自 filius 儿子、filia 女儿。不能把它解释成 file 文件加后缀，也不只限儿子。',FILI+[['晚期拉丁 filialis → 英语 filial','子女相关，尤其子女对父母的关系']],'filial affection 是子女对父母的爱，filial duty 是子女责任；filial piety 常译孝道。不同文化如何理解这些责任有差别，词本身不规定一套完全相同的行为。','filial affection；filial duty；filial piety。','parental 是父母的，filial 是子女的，观察方向相反。fraternal 是兄弟的，不能与 filial 混为一般家庭形容词。',('The letters express deep filial affection.','这些信流露出子女对父母深深的爱。'),('The essay compares different ideas of filial duty.','文章比较了不同的子女责任观念。'),sources=['https://www.etymonline.com/word/filial','https://www.oxfordlearnersdictionaries.com/definition/english/filial']),
E('unaffiliated','/ˌʌnəˈfɪlieɪtɪd/','无隶属关系的；未加入的；独立的','没有正式挂靠或加入所谈的组织，例如不属于任何政党的候选人。','un- 否定 + affiliated 有关联的；英语对状态加否定。并不自动说明这个人以前加入过后来又退出。',AFFILIATE+[['英语 affiliate → affiliated → un- + affiliated','有关联的状态 → 没有这种关联的状态']],'unaffiliated with any party 是不属于任何政党；an unaffiliated researcher 可以是未挂靠研究机构的研究者。这个词说组织关系，不等于缺乏观点、专业能力或朋友。','unaffiliated voters；an unaffiliated researcher；remain unaffiliated。','independent 范围更宽，可以说经济独立或自主思考；unaffiliated 特别说没有某种组织联系。disaffiliated 更容易强调解除过原有关系。',('She stood as a candidate unaffiliated with any party.','她以无党派候选人的身份参选。'),('The archive welcomes both affiliated and unaffiliated researchers.','这家档案馆欢迎有机构隶属和无机构隶属的研究者。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/unaffiliated','https://www.etymonline.com/word/affiliate']),
E('disaffiliate','/ˌdɪsəˈfɪlieɪt/','脱离；解除隶属或加盟关系','原来连在一个组织网络里，现在正式断开这层关系。','dis- 分开、解除 + affiliate 建立关联，是英语派生。与 unaffiliated 的没有关联状态不同，它强调解除联系这个动作。',AFFILIATE+[['英语 dis- + affiliate → disaffiliate','取消已经建立的组织关联']],'disaffiliate from an association 是脱离协会，也能说 disaffiliate a club 解除某俱乐部的隶属关系。常见于社团、工会、机构关系的正式叙述。','disaffiliate from an organisation；vote to disaffiliate；disaffiliate a branch。','resign 常说个人辞职或退出职位；disaffiliate 更突出组织关系被解除。disconnect 可以很日常，也用于设备连接；这里通常是制度性联系。',('The club voted to disaffiliate from the national federation.','俱乐部投票决定脱离全国联合会。'),('The regional group disaffiliated after a dispute over policy.','地区组织因政策争议而解除了隶属关系。'),sources=['https://www.merriam-webster.com/dictionary/disaffiliate','https://www.etymonline.com/word/affiliate']),
]
