DEFERRED={}
ALREADY={'dinosaur','pact','compact','pastel','pastille'}
CATALOG={r['id']:r for r in json.loads(Path('.cache/catalog.json').read_text())}
def rootwords(i,extra=()):return list(dict.fromkeys([w for w in ASSIGN['roots'][i]['family'] if w not in DEFERRED and '-' not in w]+list(extra)))
def rootexclude(i):
 r=CATALOG[ASSIGN['roots'][i]['id']];allwords=set(r['family'])|set(r['words'])|set(r['unmatched'])|set(ASSIGN['roots'][i]['family'])
 return {w:DEFERRED[w] for w in sorted(allwords) if w in DEFERRED}
VELOC_ROOT=dict(id='C1610',meaning='迅速；快',core='日常看走得快不快；物理学里，velocity 还要交代运动方向。',image='拉丁 velox，词干 veloc- → velocitas → 法语 vélocité／英语 velocity。',intro='这一族先掌握 velocity 就很实用。词源只是迅速，物理学后来把它限定为包含方向的速度量；这样能解释为什么匀速绕圈仍在改变 velocity。',forms='velox 的其他词形显出 veloc-；velocity 里的 c 读 /s/。其更远来源有不同推测，这里不把它与 vehicle 等词硬连成已确认的同源链。',branches=[['运动速度与方向','velocity']],contrasts='speed 作为物理量只看大小；velocity 看大小和方向。velocity 的末尾不是独立单词 city 城市。',practice='比较十米每秒与向东十米每秒；说明一辆保持相同速率转弯的车，其 velocity 为什么改变。',words=rootwords(188),exclude=rootexclude(188))
PASS_ROOT=dict(id='C0965',meaning='撒；撒过盐的食物；面团、糊',core='历史从撒盐、食物一路连到面团；现代最容易记住的是可以涂抹、塑形的一团软糊。',image='希腊 passein 撒、pastos 撒过盐的 → pasta 食物 → 拉丁 pasta 面团；经法语成 paste、pâté、pasty，经意大利语成 pasta，其他路线有 pastiche、patisserie、pastel、pastille。',intro='paste 和 pasta 是不同路线借来的同源双词；pastry 是面皮或点心，pasty 的馅饼义与苍白形容词还要区分读音。pastiche 把混合配料的画面移到艺术风格，toothpaste 则是英语直接组合的牙膏。',forms='这个 pass- 来自希腊撒这一线，与英语 pass 经过、passion 激情的来源不同。早期希腊食物名的语义联系带有解释性，不把撒盐当成每个现代词必须有的成分。',branches=[['糊与粘贴','paste, toothpaste'],['面食、酥皮与店铺','pasta, pastry, pasty, pâté, patisserie'],['画材、软片与风格拼贴','pastel, pastille, pastiche']],contrasts='pasta 通常不可数；pastry 可指不可数面皮，也可数成一块点心。pasty 馅饼读 /ˈpæsti/，形容词读 /ˈpeɪsti/。pâté 与头顶 pate 不同源、不同读音。',practice='用面团画面区分 paste、pasta、pastry；分别用 pasty 的两种读法造句；解释 pastiche 为何可以表示多种风格拼在一起。',words=rootwords(189,['pastel','pastille']),exclude=rootexclude(189))
SACC_ROOT=dict(id='C1242',meaning='袋；囊；装东西的容器',core='同一个袋子，可以变成大袋、小香袋、书包或身体里的小囊。',image='希腊 sakkos → 拉丁 saccus；经日耳曼语、古英语成 sack，经法语成 sac、sachet、satchel，经德语或低地德语成 rucksack、knapsack。英语再组合 sackcloth、sacking。',intro='词根像袋子，但英语不止一条借入路线。sack 与 sac 都读 /sæk/，前者常是大袋，后者多说生物囊。sack 的解雇、洗劫等意义各有发展，不能用一个装袋小故事冒充全部确定历史。',forms='sachet 的 ch 读 /ʃ/，satchel 的 tch 读 /tʃ/；knapsack 开头 k 不发音。希腊 sakkos 的更早来源通常联系闪米特语，具体传借路径尚有讨论。',branches=[['大袋与材料','sack, sackcloth, sacking'],['身体里的囊','sac'],['小包装与书包','sachet, satchel'],['背在身上的袋子','rucksack, knapsack']],contrasts='ransack 的主要来源是古诺斯语搜屋，现代形式可能受 sack 影响，不是 sack 的直接派生。旧酒名 sack 来自另一条干酒路线。',practice='区分 a sachet of shampoo、a school satchel 与 an air sac；从上下文判断 sacking 是解雇还是粗布；解释背包问题为什么借用 knapsack。',words=rootwords(190),exclude=rootexclude(190))
PEPON_ROOT=dict(id='C0998',meaning='熟的；熟瓜、瓜果',core='阳光把瓜晒熟的画面，藏在 pumpkin 和 melon 很远的历史里。',image='希腊 pepon 熟的、瓜 → 拉丁 pepo → 法语 pompon → 英语 pumpion → pumpkin；希腊 melon + pepon → melopepon → 拉丁缩短 melo → melon → watermelon。',intro='pumpkin 与 melon 看着不像，历史却有交会。melon 经过缩短，后半的 pepon 不再露在今天的拼写里；pumpkin 的末尾则受英语 -kin 词形影响。古代瓜名不是现代植物分类表。',forms='pumpkin 不能拆成 pump 加 kin；melon 也不能凭当前拼写看出所有历史成分。watermelon 是后来在英语中用 water 加 melon 组成的透明复合词。',branches=[['南瓜','pumpkin'],['甜瓜与西瓜','melon, watermelon']],contrasts='ripe 是词源背景，不表示只有成熟后的果实才能叫 pumpkin。古代 melon 的果实含义较宽，也不意味着现代甜瓜就是苹果。',practice='沿 pumpkin 的旧词形找出 -kin 如何替换结尾；解释 melon 的历史里为什么包含今天看不到的 pepon；用三个词各写一道食物。',words=rootwords(191),exclude=rootexclude(191))
DIN_ROOT=dict(id='C0330',meaning='可怕的；令人敬畏的；惊人的',core='dinosaur 的前半表达命名者面对古生物时的惊异，不是说每一只都巨大凶猛。',image='希腊 deinos 令人敬畏的 + sauros 蜥蜴 → 十九世纪分类名 Dinosauria → 英语 dinosaur。',intro='这一页先掌握 dinosaur。它是近代用古希腊成分造的分类名，后来也比喻笨重、落伍的人或机构；古希腊人并没有使用今天这个恐龙分类。',forms='deino-、dino- 是命名中使用的词形，英语 dinosaur 开头读 /daɪn-/。词根表写 din- 是缩略学习标签，不与英语 din 喧闹声混为一谈。',branches=[['古生物与落伍的比喻','dinosaur']],contrasts='名称有蜥蜴，不代表恐龙等于现代蜥蜴；也不是所有史前大型爬行动物都是恐龙。鸟类属于恐龙演化中的现生分支。',practice='分别用 dinosaur 谈博物馆化石和一个拒绝更新的机构；说明词源的可怕为何不是每个成员的定义。',words=rootwords(192),exclude=rootexclude(192))
PACT_ROOT=dict(id='C0940',meaning='约定；达成协议',core='把双方都要遵守的事情定下来，形成一个约。',image='拉丁 pacisci 达成协议 → pactum → 法语 pacte／英语 pact；com- + pacisci → compacisci、compactum → 英语 compact 的协议义。',intro='pact 可以是国家间的协议，也可以是朋友之间认真的约定。compact 作协议名词走共同订约这一支；它的紧凑、压实义另有相邻来源路线，不能把整词所有意思只归到约定上。',forms='pact 与固定、接牢的拉丁词族相关；现代英语不是 pack 加 t。compact 的协议名词常重读第一音节，动词压实通常重读第二音节。',branches=[['约定与协议','pact'],['共同约定的名词支线','compact']],contrasts='promise 可以由一方承诺，pact 更强调双方或多方约定。treaty 多用于国家间正式条约；朋友约好互相监督也能 make a pact。',practice='用 make a pact to 描述朋友之间的约定；看见 compact 时先判断它在说紧凑形状、压实动作还是协议。',words=rootwords(193,['compact']),exclude=rootexclude(193))
PRAT_ROOT=dict(id='C1113',meaning='草地；牧草地',core='一片长草、开阔的地面，经法语传到英语，成为北美大草原的常用名称。',image='拉丁 pratum → 通俗拉丁 *prataria → 古法语 praerie → 法语 prairie → 英语 prairie。',intro='这根最实用的词是 prairie。现代英语通常带北美草原的背景；草原可以有起伏，不要求像桌面一样平，也不等于一块人工修剪的草坪。',forms='法语中间形 praerie 解释了现代 prairie 的拼写；英美读音的主要差别在 /eə/ 与 /e/。英语早期有较旧借入形式，现代常用形式后来重新从法语传入。',branches=[['草原与相关地理表达','prairie']],contrasts='grassland 是更广的草地类型，plain 说平原地形，lawn 是草坪。prairie dog 虽带 dog，却是草原犬鼠，不是狗。',practice='用 prairie 描写一幅北美草原场景；分别说明 prairie、plain、lawn 的重点。',words=rootwords(194),exclude=rootexclude(194))
FRATER_ROOT=dict(id='C0449',meaning='兄弟；兄弟般的关系',core='亲兄弟的关系扩展为团体伙伴；也能反过来形容本应亲近的人互相伤害。',image='拉丁 frater → fraternus → fraternitas／fraternalis／fraternizare → fraternity／fraternal／fraternize；fraternity → frat。frater → 法语 frere → friar；fratr- + 杀的成分 → fratricide → fratricidal。',intro='fraternity 是团体或情谊，fraternize 是亲近交往，friar 是以兄弟称谓形成的修士名称。fratricide 和 fratricidal 则说手足、同胞或己方相残。fraternal twins 是异卵双胞胎，不只指男性。',forms='fratern- 与 fratr- 来自拉丁派生变化；friar 经法语变形，不按当前拼写硬拆。frat 是英语 fraternity 截短。fraternal 的重音不在开头，fraternize 的重音却在开头。',branches=[['情谊、团体与校园','fraternity, fraternal, frat'],['跨越界限的交往','fraternize, fraternization'],['宗教兄弟称谓','friar'],['手足与内部相残','fratricide, fratricidal']],contrasts='fraternal 是兄弟的，paternal 是父亲的。fraternization 常带不应过分亲近的语境；fraternity 不等于一场私人社交。fratricide 的己方误杀义不要求有血缘。',practice='比较 fraternal cooperation 与 fratricidal conflict；解释 frat 为什么来自英语截短；说清 fraternal twins 与 identical twins 的区别。',words=rootwords(195),exclude=rootexclude(195))
VET_ROOT=dict(id='C1629',meaning='禁止；阻止通过',core='veto 的原形不是抽象字母组合，而是一句我禁止。',image='拉丁 vetare 禁止 → 第一人称 veto 我禁止 → 英语 veto 名词 → veto 动词。',intro='英语借入了一个带完整语法形式的拉丁词，把它当成否决权或否决行为的名称，再把名词用作动词。日常说家人 vetoed a plan，是把正式否决的权力感借来形容不同意。',forms='veto 名词复数写 vetoes，动词过去式 vetoed、进行式 vetoing。词尾 -o 在这里来自拉丁第一人称形式，不是英语表示人的后缀。',branches=[['正式否决与日常夸张','veto']],contrasts='oppose 是反对，veto 通常说明有足以阻止提案的权力；是否能被推翻要看具体制度。vet 审查、兽医另有来源，不接本根。',practice='分别用 veto 作名词和动词；解释 I oppose it 与 I veto it 的力度差别。',words=rootwords(196),exclude=rootexclude(196))
FILI_ROOT=dict(id='C0424',meaning='子女；接纳为子；形成归属',core='从把一个孩子接进家庭，扩展为把一个单位或个人接入组织网络。',image='拉丁 filius 儿子／filia 女儿 → filialis → filial；ad- + filius → affiliare → affiliatio → affiliation；另由 affiliat- → affiliate → affiliated、unaffiliated、disaffiliate。',intro='filial 站在子女这一边谈父母；affiliate 一组则把收为子的历史画面转成组织关系。affiliation 有独立法语、拉丁名词借入路线，英语记录早于动词 affiliate。现代关联关系不必是完全所有或控制。',forms='ad- 在 f 前同化成 af-，因此有 affiliate 的双 f。动词末尾 -ate 读 /eɪt/，名词读 /ət/。这组 fili- 子女不同于 filament 等词中的 fil- 线。',branches=[['子女对父母','filial'],['加入与所属关系','affiliate, affiliation, affiliated'],['没有关系或解除关系','unaffiliated, disaffiliate']],contrasts='affiliated 是已有关联，unaffiliated 是没有关联，disaffiliate 是解除关系的动作。filial 子女的与 parental 父母的观察方向相反。',practice='填写一条 institutional affiliation；比较 an affiliate、be affiliated with 与 disaffiliate from；说明 unaffiliated 不一定代表曾经退出。',words=rootwords(197),exclude=rootexclude(197))
